    if (r.status === 429) throw new Error("AIsa rate limited — try again in a moment.");
    if (!r.ok) throw new Error(`AIsa chat failed: ${r.status}`);
    const j = await r.json();
    return { reply: j.choices[0].message.content as string };
  });
